export type UserArea =
  | 'Contabilidad'
  | 'Presupuesto'
  | 'Despacho'
  | 'Tesorería'
  | 'Rentas'
  | 'Pensiones'
  | 'General'
  | 'Otra';

export const USER_AREAS: UserArea[] = [
  'Contabilidad',
  'Presupuesto',
  'Despacho',
  'Tesorería',
  'Rentas',
  'Pensiones',
  'General',
  'Otra',
];

export interface User {
  id: number;
  nombre: string;
  alias: string;
  role: 'admin' | 'soporte' | 'user';
  area?: UserArea;
  telefono?: string;
  activo?: boolean;
  createdAt?: string;
}

export interface AuthResponse {
  access_token: string;
  user: User;
}
